export async function POST() {
  try {
    const db = await getDb()
    await db.run(`
      CREATE TABLE IF NOT EXISTS sedimentation_survey (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        p_no TEXT, district TEXT,
        us_mh TEXT, ds_mh TEXT,
        us_lat REAL, us_lng REAL,
        ds_lat REAL, ds_lng REAL,
        sedi_dh REAL DEFAULT 0,
        fd_depth REAL DEFAULT 0,
        cls INTEGER DEFAULT 1,
        count INTEGER DEFAULT 1,
        inv_date TEXT, memo TEXT
      )
    `)
    await db.run('DELETE FROM sedimentation_survey')
    let inserted = 0
    for (const r of SED_DATA) {
      await db.run(
        `INSERT INTO sedimentation_survey (p_no, district, us_mh, ds_mh, us_lat, us_lng, ds_lat, ds_lng, sedi_dh, fd_depth, cls, count, inv_date, memo)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [r.p_no, r.district, r.us_mh, r.ds_mh, r.us_lat, r.us_lng, r.ds_lat, r.ds_lng, r.sedi_dh, r.fd_depth, r.cls, r.count, r.inv_date, r.memo]
      )
      inserted++
    }
    const cnt = await db.get('SELECT COUNT(*) as n FROM sedimentation_survey') as any
    return NextResponse.json({ success: true, inserted, total: cnt.n })
  } catch (err) {
    console.error('import-sedimentation-survey error:', err)
    return NextResponse.json({ error: String(err) }, { status: 500 })
  }
}
